"""Refresh the Claude Code model picker from a provider's /v1/models endpoint.

The provider is described the same way Claude Code describes one: an
ANTHROPIC_BASE_URL plus an ANTHROPIC_AUTH_TOKEN or ANTHROPIC_API_KEY. The
generated rows replace ``modelPicker.options`` in the target settings file, or
are written as a standalone fragment with ``--output``.
"""

import argparse
import json
import os
import re
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any

_FIRST_DIGIT = re.compile(r"\d")
_ANTHROPIC_MODEL = re.compile(r"^(?:anthropic[./:-])?claude(?:$|[./:-])", re.I)
_BUILD_SUFFIX = re.compile(r"-\d{3,}$")


class RefreshError(Exception):
    """A provider or settings problem that should be reported to the user."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    # A bearer token must not follow a redirect to an unexpected host.
    def redirect_request(
        self,
        req: urllib.request.Request,
        fp: Any,
        code: int,
        msg: str,
        headers: Any,
        newurl: str,
    ) -> None:
        return None


def models_url(base_url: str) -> str:
    """Build the provider model-list URL from an Anthropic-style base URL."""
    parts = urllib.parse.urlsplit(base_url.strip())
    if not parts.scheme or not parts.netloc:
        raise RefreshError(f"Not an absolute URL: {base_url!r}")

    path = parts.path.rstrip("/")
    if not path.endswith("/v1"):
        path = f"{path}/v1"
    path = f"{path}/models"

    query = urllib.parse.urlencode({"limit": "1000"})
    return urllib.parse.urlunsplit((parts.scheme, parts.netloc, path, query, ""))


def auth_headers(
    *,
    token: str | None = None,
    auth: str | None = None,
) -> dict[str, str]:
    """Return the single provider credential header for an Anthropic request.

    API keys use ``x-api-key``. Credentials that accept bearer auth use
    ``Authorization``. The header is never duplicated and the credential is
    never put in the request body.
    """
    if token is None:
        api_key = os.environ.get("ANTHROPIC_API_KEY")
        bearer = os.environ.get("ANTHROPIC_AUTH_TOKEN")
        if auth is None:
            if api_key:
                auth, token = "api-key", api_key
            elif bearer:
                auth, token = "bearer", bearer
        elif auth == "api-key":
            token = api_key
        else:
            token = bearer

    if not token:
        raise RefreshError(
            "No provider credential. Set ANTHROPIC_API_KEY for api-key auth "
            "or ANTHROPIC_AUTH_TOKEN for bearer auth, or pass --token."
        )

    if auth == "bearer":
        return {
            "anthropic-version": "2023-06-01",
            "Authorization": f"Bearer {token}",
        }
    return {
        "anthropic-version": "2023-06-01",
        "x-api-key": token,
    }


def fetch_models(url: str, *, headers: dict[str, str], timeout: float) -> list[Any]:
    """Fetch and validate the provider's model list."""
    request = urllib.request.Request(url, headers=headers, method="GET")
    opener = urllib.request.build_opener(_NoRedirect)
    try:
        with opener.open(request, timeout=timeout) as response:
            payload = json.load(response)
    except urllib.error.HTTPError as error:
        raise RefreshError(f"Provider returned HTTP {error.code} for {url}") from error
    except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as error:
        raise RefreshError(f"Could not read models from {url}: {error}") from error

    data = payload.get("data") if isinstance(payload, dict) else None
    if not isinstance(data, list):
        raise RefreshError(f"Provider response has no data array: {url}")
    return data


def model_class(model_id: str) -> tuple[str, str]:
    """Split a model ID into its non-numeric prefix and its version."""
    match = _FIRST_DIGIT.search(model_id)
    if match is None:
        return model_id, ""
    index = match.start()
    return model_id[:index], model_id[index:]


def _version_key(version: str) -> tuple[tuple[int, int | str], ...]:
    """Compare versions component-wise, numerically when a component is a number."""
    key: list[tuple[int, int | str]] = []
    for part in version.replace("-", ".").split("."):
        if part.isdigit():
            key.append((1, int(part)))
        elif part:
            key.append((0, part.lower()))
    return tuple(key)


def latest_by_class(options: list[dict]) -> list[dict]:
    """Keep only the highest version for each model class."""
    latest: dict[str, dict] = {}
    order: list[str] = []
    for option in options:
        prefix, version = model_class(option["model"])
        current = latest.get(prefix)
        if current is None:
            latest[prefix] = option
            order.append(prefix)
            continue
        _, current_version = model_class(current["model"])
        if _version_key(version) > _version_key(current_version):
            latest[prefix] = option
    return [latest[prefix] for prefix in order]


def generate_label(model_id: str) -> str:
    """Build a short label from a model ID: provider path and build number removed."""
    name = _BUILD_SUFFIX.sub("", model_id.rsplit("/", 1)[-1])
    parts: list[str] = []
    for token in name.replace("_", "-").split("-"):
        if token and token.isdigit() and parts and parts[-1].isdigit():
            parts[-1] = f"{parts[-1]}.{token}"
        elif token:
            parts.append(token)
    return " ".join(parts) or model_id


def build_options(
    entries: list[Any],
    *,
    description: str | None = None,
    include_anthropic: bool = False,
) -> list[dict]:
    """Convert provider model records into modelPicker rows."""
    options: list[dict] = []
    seen: set[str] = set()
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        model_id = entry.get("id")
        if not isinstance(model_id, str):
            continue
        model_id = model_id.strip()
        if not model_id or model_id in seen:
            continue
        seen.add(model_id)
        # Claude Code ships the Anthropic lineup; only custom models are added.
        if not include_anthropic and _ANTHROPIC_MODEL.match(model_id):
            continue

        display_name = entry.get("display_name")
        label = display_name.strip() if isinstance(display_name, str) else ""
        row: dict[str, Any] = {
            "model": model_id,
            "label": label if label and label != model_id else generate_label(model_id),
        }
        if description:
            row["description"] = description
        options.append(row)

    if not options:
        raise RefreshError("Provider returned no usable models")
    return latest_by_class(options)


def _write_json(path: Path, data: dict) -> None:
    """Write JSON atomically, preserving an existing file's permissions."""
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o777 if path.exists() else None
    handle = tempfile.NamedTemporaryFile(
        "w",
        dir=path.parent,
        prefix=f".{path.name}.",
        delete=False,
        encoding="utf-8",
    )
    try:
        with handle:
            json.dump(data, handle, indent=2)
            handle.write("\n")
        if mode is not None:
            os.chmod(handle.name, mode)
        os.replace(handle.name, path)
    except BaseException:
        Path(handle.name).unlink(missing_ok=True)
        raise


def _settings_document(settings_path: Path, options: list[dict]) -> dict:
    """Return the settings document with modelPicker.options replaced."""
    data: dict[str, Any] = {}
    if settings_path.exists():
        try:
            loaded = json.loads(settings_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as error:
            raise RefreshError(f"Invalid JSON in {settings_path}: {error}") from error
        if not isinstance(loaded, dict):
            raise RefreshError(f"Settings file is not a JSON object: {settings_path}")
        data = loaded

    picker = data.get("modelPicker")
    if not isinstance(picker, dict):
        picker = {}
    picker["options"] = options
    data["modelPicker"] = picker
    return data


def update_settings(settings_path: Path, options: list[dict]) -> None:
    """Replace modelPicker.options in an existing Claude settings file."""
    _write_json(settings_path, _settings_document(settings_path, options))


def default_settings_path() -> Path:
    config_dir = os.environ.get("CLAUDE_CONFIG_DIR")
    root = Path(config_dir) if config_dir else Path.home() / ".claude"
    return root / "settings.json"


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Refresh Claude Code modelPicker.options from a provider's "
            "/v1/models endpoint."
        )
    )
    parser.add_argument(
        "--url",
        default=os.environ.get("ANTHROPIC_BASE_URL"),
        help="Provider base URL (default: $ANTHROPIC_BASE_URL)",
    )
    parser.add_argument(
        "--token",
        help="Provider token (default: $ANTHROPIC_AUTH_TOKEN or $ANTHROPIC_API_KEY)",
    )
    parser.add_argument(
        "--auth",
        choices=("api-key", "bearer"),
        help=(
            "Credential header (default: x-api-key from $ANTHROPIC_API_KEY, "
            "then bearer from $ANTHROPIC_AUTH_TOKEN)"
        ),
    )
    parser.add_argument(
        "--settings",
        type=Path,
        help="Settings file to update (default: $CLAUDE_CONFIG_DIR/settings.json)",
    )
    parser.add_argument(
        "--output",
        type=Path,
        help="Write a standalone modelPicker fragment instead of updating settings",
    )
    parser.add_argument(
        "--description",
        help="Description to add to every generated picker row",
    )
    parser.add_argument(
        "--include-anthropic",
        action="store_true",
        help="Include Claude models (excluded by default; Claude Code ships them)",
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=20.0,
        help="Request timeout in seconds (default: 20)",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Print the resulting settings or fragment without writing",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    if not args.url:
        parser.error("no provider URL; set ANTHROPIC_BASE_URL or pass --url")
    if args.settings and args.output:
        parser.error("--settings and --output are mutually exclusive")

    try:
        url = models_url(args.url)
        entries = fetch_models(
            url,
            headers=auth_headers(token=args.token, auth=args.auth),
            timeout=args.timeout,
        )
        options = build_options(
            entries,
            description=args.description,
            include_anthropic=args.include_anthropic,
        )
    except RefreshError as error:
        print(f"refresh-models: {error}", file=sys.stderr)
        return 1

    settings_path = args.settings or default_settings_path()
    try:
        if args.output:
            result = {"modelPicker": {"options": options}}
        else:
            result = _settings_document(settings_path, options)

        if args.dry_run:
            print(json.dumps(result, indent=2))
            return 0

        if args.output:
            _write_json(args.output, result)
            destination = args.output
        else:
            update_settings(settings_path=settings_path, options=options)
            destination = settings_path
    except (OSError, RefreshError) as error:
        print(f"refresh-models: {error}", file=sys.stderr)
        return 1

    print(f"Refreshed {len(options)} models in {destination}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
